1: /** @module @category Utility */
2: import { useEffect, useRef } from 'react';
3: 
4: /**
5:  * @beta
6:  *
7:  * This hook creates an AbortController that lasts either until the previous AbortController
8:  * is aborted or until the component unmounts. This can be used to ensure that all fetch requests
9:  * are cancelled when a component is unmounted.
10:  *
11:  * @example
12:  * ```tsx
13:  * import { useAbortController } from "@openmrs/esm-framework";
14:  *
15:  * function MyComponent() {
16:  *  const abortController = useAbortController();
17:  *  const { data } = useSWR(key, (key) => openmrsFetch(key, { signal: abortController.signal }));
18:  *
19:  *  return (
20:  *    // render something with data
21:  *  );
22:  * }
23:  * ```
24:  */
25: export function useAbortController() {
26:   const abortController = useRef<AbortController>();
27: 
28:   if (!abortController.current || abortController.current.signal.aborted) {
29:     abortController.current = new AbortController();
30:   }
31: 
32:   useEffect(() => {
33:     const ac = abortController.current;
34:     return () => ac?.abort();
35:   }, []);
36: 
37:   return abortController.current;
38: }
39: 
40: export default useAbortController;
